143|const seedBuiltinRolesSqlServer = async (actor: ActorRef): Promise<void> => {
144|  const actorSql = actor === null ? 'NULL' : actor.toString();
145|  const sourceRows = BUILTIN_ROLES.map(
146|    (role) => `(${role.id}, N'${escapeSqlServerLiteral(role.name)}', N'${escapeSqlServerLiteral(role.note)}', ${actorSql}, ${actorSql})`,
147|  ).join(',\n');
148|
149|  await prisma().$executeRawUnsafe(`
150|SET IDENTITY_INSERT [base_roles] ON;
151|MERGE [base_roles] AS target
152|USING (VALUES
153|${sourceRows}
154|) AS source ([id], [name], [note], [created_by], [updated_by])
155|ON target.[name] = source.[name]
156|WHEN MATCHED THEN
157|  UPDATE SET [note] = source.[note], [updated_by] = source.[updated_by]
158|WHEN NOT MATCHED THEN
159|  INSERT ([id], [name], [note], [created_by], [updated_by])
160|  VALUES (source.[id], source.[name], source.[note], source.[created_by], source.[updated_by]);
161|SET IDENTITY_INSERT [base_roles] OFF;
162|`);
